        def add_group(
            page: RibbonPage,
            caption: str,
            *,
            large: tuple[str, ...] = (),
            small: tuple[str, ...] = (),
            widgets: tuple[QWidget, ...] = (),
        ) -> RibbonGroup:
            group = RibbonGroup(caption)
            for key in large:
                group.add_large_action(self.actions[key])
            for key in small:
                group.add_small_action(self.actions[key])
            for widget in widgets:
                group.add_widget(widget)
            page.add_group(group)
            return group

