    def _handle_geometry_batch_target_click(
        self,
        payload: object,
    ) -> None:
        if not isinstance(payload, dict):
            return
        target = payload.get("tag")
        if target is None:
            return
        target_tag = int(target)
        operation = self._geometry_line_edit_operation
        label = operation.capitalize()
