    def _select_generated_fe_for_surfaces(
        self,
        surface_tags,
    ) -> None:
        tags = sorted({
            int(tag)
            for tag in surface_tags
            if int(tag) in self.project.surfaces
        })
        if not tags:
            return
        if not self._ensure_surface_meshes(
            tags,
            title="Select Generated FE",
        ):
            return

        element_tags: set[int] = set()
        for surface_tag in tags:
            surface = self.project.surfaces.get(int(surface_tag))
            if surface is None:
                continue
            for element_tag in surface.generated_element_tags:
                element = self.model.elements.get(int(element_tag))
                if (
                    element is not None
                    and element.element_type in SHELL_ELEMENT_TYPES
                ):
                    element_tags.add(int(element_tag))
        if not element_tags:
            return
        self.viewport.set_display_domain("fe")
        self.selection.set_selection(elements=element_tags)
        self.status_message.setText(
            f"Selected {len(element_tags)} generated Shell FE element(s)"
        )

    def _assign_shell_section_to_surfaces(
        self,
        surface_tags,
    ) -> None:
        tags = sorted({
            int(tag)
            for tag in surface_tags
            if int(tag) in self.project.surfaces
        })
        if not tags:
            return
        if not self._ensure_prerequisite(
            title="Assign Shell Section to Surface",
            message="No Shell Sections exist yet. Create one now?",
            action_label="Create Shell Section Now...",
            available=lambda: bool(self._shell_sections()),
            creator=self._create_shell_section,
        ):
            return

        section_tags = sorted(self._shell_sections())
        labels = [
            f"{section_tag} - {self.project.sections[section_tag].name}"
            for section_tag in section_tags
        ]
        current = {
            self.project.surfaces[tag].section_tag
            for tag in tags
        }
        current_index = 0
        if len(current) == 1:
            current_tag = next(iter(current))
            if current_tag in section_tags:
                current_index = section_tags.index(current_tag)

        label, ok = QInputDialog.getItem(
            self,
            "Assign Shell Section to Surface",
            f"Assign to {len(tags)} Surface geometry object(s):",
            labels,
            current_index,
            False,
        )
        if not ok:
            return
        section_tag = section_tags[labels.index(label)]

        before = self.project.to_dict()
        updated_elements = 0
        try:
            for tag in tags:
                surface = self.project.surfaces[tag]
                surface.section_tag = section_tag
                for element_tag in surface.generated_element_tags:
                    element = self.model.elements.get(int(element_tag))
                    if (
                        element is not None
                        and element.element_type in SHELL_ELEMENT_TYPES
                    ):
                        element.section_tag = section_tag
                        updated_elements += 1
                self.project._validate_surface_geometry(surface)
        except (TypeError, ValueError) as exc:
            self.project = ProjectDatabase.from_dict(before)
            self.model = self.project.model
            self._refresh_all()
            QMessageBox.warning(
                self,
                "Assign Shell Section to Surface",
                str(exc),
            )
            return

        self._refresh_all(
            f"Assigned Shell Section {section_tag} to {len(tags)} "
            f"Surface(s) · synchronized {updated_elements} generated "
            "Shell element(s)"
        )
        self.viewport.set_display_domain("geometry")
        self._record_project_change(
            f"Assign Shell Section {section_tag} to Surface(s)",
            before,
        )

    def _preview_surface_meshes(self, surface_tags) -> None:
        tags = sorted({
            int(tag)
            for tag in surface_tags
            if int(tag) in self.project.surfaces
        })
        if not tags:
            return
        unconfigured = [
            tag
            for tag in tags
            if not self.project.surfaces[tag].mesh_recipe_configured
        ]
        for tag in unconfigured:
            if not self._ask_create_prerequisite(
                title="Preview Surface Mesh",
                message=(
                    f"Surface {tag} needs a Surface Mesh / Shell recipe "
                    "before it can be previewed. Configure it now?"
                ),
                action_label=f"Configure Surface {tag} Mesh Now...",
            ):
                return
            if not self._configure_surface_mesh(tag, generate=False):
                return
            surface = self.project.surfaces.get(int(tag))
            if surface is None or not surface.mesh_recipe_configured:
                return
        total = 0
        summaries = []
        try:
            for tag in tags:
                nu, nv = surface_preview_divisions(
                    self.project.surfaces[tag]
                )
                total += nu * nv
                summaries.append(f"S{tag}: {nu}×{nv}")
        except ValueError as exc:
            QMessageBox.warning(self, "Preview Surface Mesh", str(exc))
            return

        self.viewport.set_display_domain("geometry")
        self.viewport.show_surface_mesh_preview(tags)
        self.status_message.setText(
            f"Mesh preview · {len(tags)} Surface(s) · "
            f"{total} planned Shell element(s) · "
            + " · ".join(summaries)
        )

    def _clear_surface_mesh_preview(self) -> None:
        self.viewport.clear_surface_mesh_preview()
        self.status_message.setText("Surface mesh preview cleared")

    def _audit_surface_conformity(
        self,
        surface_tags=None,
    ) -> None:
        tags = (
            sorted({
                int(tag)
                for tag in surface_tags
                if int(tag) in self.project.surfaces
            })
            if surface_tags is not None
            else sorted(self.project.surfaces)
        )
        if len(tags) < 2:
            QMessageBox.information(
                self,
                "Surface Conformity Audit",
                "Select at least two Surface geometry objects.",
            )
            return
        try:
            report = audit_surface_conformity(
                self.project,
                tags,
            )
        except ValueError as exc:
            QMessageBox.warning(
                self,
                "Surface Conformity Audit",
                str(exc),
            )
            return

        rows = [
            ("Surfaces checked", report.surface_count),
            ("Shared edges", report.shared_edge_count),
            ("Issues", len(report.issues)),
            (
                "Status",
                "Conforming"
                if report.conforming
                else "Review required",
            ),
        ]
        for index, issue in enumerate(report.issues[:12], start=1):
            rows.append((f"Issue {index}", issue.message))
        if len(report.issues) > 12:
            rows.append((
                "More",
                f"{len(report.issues) - 12} additional issue(s)",
            ))
        self.properties_panel.set_properties(
            "Surface Conformity Audit",
            rows,
        )
        self.properties_dock.raise_()
        self.status_message.setText(
            f"Surface conformity audit: {report.shared_edge_count} shared "
            f"edge(s), {len(report.issues)} issue(s)"
        )

    def _audit_surface_mesh_integrity(
        self,
        surface_tags=None,
    ) -> None:
        tags = (
            sorted({
                int(tag)
                for tag in surface_tags
                if int(tag) in self.project.surfaces
            })
            if surface_tags is not None
            else sorted(self.project.surfaces)
        )
        if not tags:
            return

        report = audit_surface_mesh_integrity(self.project, tags)
        rows = [
            ("Surfaces checked", report.surface_count),
            ("Stale meshes", len(report.stale_states)),
            (
                "Status",
                "Healthy" if report.healthy else "Review required",
            ),
        ]
        for state in report.stale_states[:12]:
            details = []
            if state.missing_element_tags:
                details.append(
                    f"{len(state.missing_element_tags)} missing element(s)"
                )
            if state.foreign_element_tags:
                details.append(
                    f"{len(state.foreign_element_tags)} foreign element(s)"
                )
            if state.untracked_owned_element_tags:
                details.append(
                    f"{len(state.untracked_owned_element_tags)} "
                    "owned/untracked element(s)"
                )
            if state.missing_node_tags:
                details.append(
                    f"{len(state.missing_node_tags)} missing node(s)"
                )
            rows.append((
                f"Surface {state.surface_tag}",
                "; ".join(details) or "Stale tracking",
            ))
        if len(report.stale_states) > 12:
            rows.append((
                "More",
                f"{len(report.stale_states) - 12} additional stale Surface(s)",
            ))

        self.properties_panel.set_properties(
            "Surface Mesh Integrity Audit",
            rows,
        )
        self.properties_dock.raise_()
        self.status_message.setText(
            f"Surface mesh integrity audit: {report.surface_count} checked · "
            f"{len(report.stale_states)} stale"
        )

    def _inspect_surface_edges(self, surface_tag: int) -> None:
        tag = int(surface_tag)
        surface = self.project.surfaces.get(tag)
        if surface is None:
            return

        infos = [
            surface_edge_info(self.project, tag, edge_index)
            for edge_index in range(1, 5)
        ]
        unit_system = UnitSystem.from_mapping(self.project.units)
        rows = [
            ("Surface", f"{tag} - {surface.name}"),
            ("Convention", "E1 P1→P2 · E2 P2→P3 · E3 P3→P4 · E4 P4→P1"),
        ]
        corner_labels = {
            1: "P1→P2",
            2: "P2→P3",
            3: "P3→P4",
            4: "P4→P1",
        }
        for info in infos:
            adjacency = (
                "Boundary"
                if not info.neighbor_edges
                else ", ".join(
                    f"S{other}:E{edge}"
                    for other, edge in info.neighbor_edges
                )
            )
            nodes = (
                ", ".join(map(str, info.live_node_tags))
                if info.live_node_tags
                else "Unmeshed"
            )
            rows.extend([
                (
                    f"E{info.edge_index} {corner_labels[info.edge_index]}",
                    f"L={info.length:g} {unit_system.length} · "
                    f"requested {info.requested_divisions} div · "
                    f"live {info.actual_divisions} div · "
                    f"{info.connectivity_status}",
                ),
                (f"E{info.edge_index} adjacency", adjacency),
                (f"E{info.edge_index} FE nodes", nodes),
            ])

        self.viewport.show_surface_edge_preview(
            [(tag, edge_index) for edge_index in range(1, 5)]
        )
        self.properties_panel.set_properties("Surface Edges", rows)
        self.properties_dock.raise_()
        self.status_message.setText(
            f"Surface {tag}: inspected 4 geometry/FE edges"
        )

    def _select_surface_edge_nodes(self, surface_tag: int) -> None:
        tag = int(surface_tag)
        surface = self.project.surfaces.get(tag)
        if surface is None:
            return
        if not self._ensure_surface_meshes(
            [tag],
            title="Select Surface Edge FE Nodes",
        ):
            return

        infos = [
            surface_edge_info(self.project, tag, edge_index)
            for edge_index in range(1, 5)
        ]
        self.viewport.show_surface_edge_preview(
            [(tag, edge_index) for edge_index in range(1, 5)]
        )
        labels = []
        for info in infos:
            shared = (
                "boundary"
                if not info.neighbor_edges
                else "shared with " + ", ".join(
                    f"S{other}:E{edge}"
                    for other, edge in info.neighbor_edges
                )
            )
            labels.append(
                f"Edge {info.edge_index} · {len(info.live_node_tags)} node(s) · "
                f"{shared}"
            )

        label, ok = QInputDialog.getItem(
            self,
            "Select Surface Edge FE Nodes",
            f"Surface {tag} edge:",
            labels,
            0,
            False,
        )
        if not ok:
            self.viewport.clear_surface_edge_preview()
            return
        edge_index = labels.index(label) + 1
        try:
            node_tags = surface_edge_node_tags(
                self.project,
                tag,
                edge_index,
            )
        except ValueError as exc:
            self.viewport.clear_surface_edge_preview()
            QMessageBox.warning(
                self,
                "Select Surface Edge FE Nodes",
                str(exc),
            )
            return

        self.viewport.clear_surface_edge_preview(render=False)
        self.viewport.set_display_domain("fe")
        self.selection.set_selection(nodes=set(node_tags))
        self.status_message.setText(
            f"Surface {tag} Edge {edge_index}: selected "
            f"{len(node_tags)} ordered FE node(s)"
        )

    def _manage_surface_edge_support(
        self,
        surface_tag: int,
        *,
        support_tag: int | None = None,
    ) -> None:
        tag = int(surface_tag)
        surface = self.project.surfaces.get(tag)
        if surface is None:
            return
        if not self._ensure_surface_meshes(
            [tag],
            title="Managed Surface Edge Support",
        ):
            return
        try:
            infos = [
                surface_edge_info(self.project, tag, edge_index)
                for edge_index in range(1, 5)
            ]
        except ValueError as exc:
            QMessageBox.warning(
                self,
                "Managed Surface Edge Support",
                str(exc),
            )
            return

        existing_by_edge = {
            support.edge_index: support
            for support in self.project.surface_edge_supports.values()
            if support.surface_tag == tag
        }
        labels = []
        for info in infos:
            existing = existing_by_edge.get(info.edge_index)
            suffix = (
                f" · current {classify_fixity(existing.fixity)}"
                if existing is not None else ""
            )
            labels.append(
                f"Edge {info.edge_index} · {len(info.live_node_tags)} FE node(s)"
                + suffix
            )
        target_support = (
            self.project.surface_edge_supports.get(int(support_tag))
            if support_tag is not None
            else None
        )
        if (
            target_support is not None
            and target_support.surface_tag == tag
        ):
            edge_index = int(target_support.edge_index)
        else:
            label, ok = QInputDialog.getItem(
                self,
                "Managed Surface Edge Support",
                f"Surface {tag} edge:",
                labels,
                0,
                False,
            )
            if not ok:
                return
            edge_index = labels.index(label) + 1
        existing = existing_by_edge.get(edge_index)
        initial = existing.fixity if existing is not None else None
        dialog = RestraintDialog(
            initial=initial,
            parent=self,
            ndm=self.model.ndm,
            ndf=self.model.ndf,
        )
        if not dialog.exec():
            return
        fixity = tuple(int(value) for value in dialog.fixity())
        if not any(fixity):
            QMessageBox.warning(
                self,
                "Managed Surface Edge Support",
                "Choose at least one restrained DOF.",
            )
            return

        before = self.project.to_dict()
        try:
            if existing is None:
                support = SurfaceEdgeSupportData(
                    tag=self.project.next_surface_edge_support_tag(),
                    name=f"S{tag} E{edge_index} Support",
                    surface_tag=tag,
                    edge_index=edge_index,
                    fixity=fixity,
                )
                self.project.add_surface_edge_support(support)
            else:
                support = SurfaceEdgeSupportData(
                    tag=existing.tag,
                    name=existing.name,
                    surface_tag=tag,
                    edge_index=edge_index,
                    fixity=fixity,
                    generated_node_tags=list(
                        existing.generated_node_tags
                    ),
                )
                node_tags = replace_surface_edge_support(
                    self.project,
                    support,
                )
            if existing is None:
                node_tags = sync_surface_edge_support(
                    self.project,
                    support.tag,
                )
        except (TypeError, ValueError, IndexError) as exc:
            self.project = ProjectDatabase.from_dict(before)
            self.model = self.project.model
            self._refresh_all()
            QMessageBox.warning(
                self,
                "Managed Surface Edge Support",
                str(exc),
            )
            return

        self.model = self.project.model
        self._refresh_all(
            f"{'Updated' if existing is not None else 'Created'} managed "
            f"{classify_fixity(support.fixity)} support on "
            f"Surface {tag} Edge {edge_index} · {len(node_tags)} node(s)"
        )
        self.viewport.set_display_domain("geometry")
        self.viewport.show_surface_edge_preview([(tag, edge_index)])
        self._show_surface_geometry_properties(tag)
        self._record_project_change(
            f"Managed support Surface {tag} Edge {edge_index}",
            before,
        )

    def _remove_surface_edge_support(self, surface_tag: int) -> None:
        tag = int(surface_tag)
        supports = sorted(
            (
                support
                for support in self.project.surface_edge_supports.values()
                if support.surface_tag == tag
            ),
            key=lambda item: item.edge_index,
        )
        if not supports:
            QMessageBox.information(
                self,
                "Remove Managed Surface Edge Support",
                f"Surface {tag} has no managed edge supports.",
            )
            return
        labels = [
            f"Edge {support.edge_index} · "
            f"{classify_fixity(support.fixity)} · Support {support.tag}"
            for support in supports
        ]
        label, ok = QInputDialog.getItem(
            self,
            "Remove Managed Surface Edge Support",
            f"Surface {tag} support:",
            labels,
            0,
            False,
        )
        if not ok:
            return
        support = supports[labels.index(label)]

        before = self.project.to_dict()
        try:
            changed = remove_surface_edge_support(
                self.project,
                support.tag,
            )
        except ValueError as exc:
            self.project = ProjectDatabase.from_dict(before)
            self.model = self.project.model
            self._refresh_all()
            QMessageBox.warning(
                self,
                "Remove Managed Surface Edge Support",
                str(exc),
            )
            return

        self.model = self.project.model
        self._refresh_all(
            f"Removed managed support {support.tag} from Surface {tag} "
            f"Edge {support.edge_index} · released {len(changed)} node(s)"
        )
        self.viewport.set_display_domain("geometry")
        self._show_surface_geometry_properties(tag)
        self._record_project_change(
            f"Remove managed Surface edge support {support.tag}",
            before,
        )

    def _manage_surface_edge_line_load(
        self,
        surface_tag: int,
        *,
        edge_load_tag: int | None = None,
    ) -> None:
        tag = int(surface_tag)
        surface = self.project.surfaces.get(tag)
        if surface is None:
            return
        if not self._ensure_surface_meshes(
            [tag],
            title="Managed Surface Edge Line Load",
        ):
            return
        if not self._plain_load_patterns():
            if not self._ensure_plain_load_pattern(
                title="Managed Surface Edge Line Load"
            ):
                return

        try:
            infos = [
                surface_edge_info(self.project, tag, edge_index)
                for edge_index in range(1, 5)
            ]
        except ValueError as exc:
            QMessageBox.warning(
                self,
                "Managed Surface Edge Line Load",
                str(exc),
            )
            return

        edge_labels = []
        for info in infos:
            count = sum(
                1
                for edge_load in self.project.surface_edge_loads.values()
                if (
                    edge_load.surface_tag == tag
                    and edge_load.edge_index == info.edge_index
                )
            )
            suffix = f" · {count} managed load(s)" if count else ""
            edge_labels.append(
                f"Edge {info.edge_index} · "
                f"{len(info.live_node_tags)} FE node(s){suffix}"
            )
        target_edge_load = (
            self.project.surface_edge_loads.get(int(edge_load_tag))
            if edge_load_tag is not None
            else None
        )
        if (
            target_edge_load is not None
            and target_edge_load.surface_tag == tag
        ):
            edge_index = int(target_edge_load.edge_index)
        else:
            edge_label, ok = QInputDialog.getItem(
                self,
                "Managed Surface Edge Line Load",
                f"Surface {tag} edge:",
                edge_labels,
                0,
                False,
            )
            if not ok:
                return
            edge_index = edge_labels.index(edge_label) + 1

        existing = sorted(
            (
                edge_load
                for edge_load in self.project.surface_edge_loads.values()
                if (
                    edge_load.surface_tag == tag
                    and edge_load.edge_index == edge_index
                )
            ),
            key=lambda item: (item.pattern_tag, item.tag),
        )
        if (
            target_edge_load is not None
            and target_edge_load in existing
        ):
            editing = target_edge_load
        else:
            choices = ["Create new line load..."] + [
                f"Edit Load {item.tag} · Pattern {item.pattern_tag} · {item.name}"
                for item in existing
            ]
            choice, ok = QInputDialog.getItem(
                self,
                "Managed Surface Edge Line Load",
                "Definition:",
                choices,
                0,
                False,
            )
            if not ok:
                return
            editing = (
                None if choice == choices[0]
                else existing[choices.index(choice) - 1]
            )

        dialog = SurfaceEdgeLoadDialog(
            self._plain_load_patterns(),
            surface_tag=tag,
            edge_index=edge_index,
            edge_load=editing,
            next_tag=self.project.next_surface_edge_load_tag(),
            units=self.project.units,
            new_pattern_callback=self._create_plain_pattern_dependency,
            parent=self,
        )
        if not dialog.exec():
            return
        edge_load = dialog.data()

        before = self.project.to_dict()
        try:
            if editing is None:
                self.project.add_surface_edge_load(edge_load)
                generated = sync_surface_edge_load(
                    self.project,
                    edge_load.tag,
                )
            else:
                edge_load.generated_nodal_load_tags = list(
                    editing.generated_nodal_load_tags
                )
                generated = replace_surface_edge_load(
                    self.project,
                    edge_load,
                )
        except (TypeError, ValueError, IndexError) as exc:
            self.project = ProjectDatabase.from_dict(before)
            self.model = self.project.model
            self._refresh_all()
            QMessageBox.warning(
                self,
                "Managed Surface Edge Line Load",
                str(exc),
            )
            return

        self.model = self.project.model
        self._refresh_all(
            f"{'Updated' if editing is not None else 'Created'} managed "
            f"line load {edge_load.tag} on Surface {tag} Edge {edge_index} · "
            f"{len(generated)} equivalent nodal load(s)"
        )
        self.viewport.set_display_domain("geometry")
        self.viewport.show_surface_edge_load_preview(
            tag,
            edge_index,
            edge_load.values_per_length,
        )
        self._show_surface_geometry_properties(tag)
        self._record_project_change(
            f"Managed line load Surface {tag} Edge {edge_index}",
            before,
        )

