    def _manage_surface_shell_recorder(
        self,
        surface_tag: int,
        *,
        recorder_tag: int | None = None,
    ) -> None:
        tag = int(surface_tag)
        surface = self.project.surfaces.get(tag)
        if surface is None:
            return
        if not self._ensure_surface_meshes(
            [tag],
            title="Managed Surface Shell Recorder",
        ):
            return

        existing = sorted(
            (
                recorder
                for recorder in self.project.surface_recorders.values()
                if recorder.surface_tag == tag
            ),
            key=lambda item: item.tag,
        )
        target = next(
            (
                item
                for item in existing
                if recorder_tag is not None
                and item.tag == int(recorder_tag)
            ),
            None,
        )
        if target is not None:
            editing = target
        else:
            choices = ["Create new recorder..."] + [
                f"Edit Recorder {item.tag} · {item.response} · "
                f"GP {item.section_number}"
                for item in existing
            ]
            choice, ok = QInputDialog.getItem(
                self,
                "Managed Surface Shell Recorder",
                f"Surface {tag}:",
                choices,
                0,
                False,
            )
            if not ok:
                return
            editing = (
                None if choice == choices[0]
                else existing[choices.index(choice) - 1]
            )

        dialog = SurfaceRecorderDialog(
            surface_tag=tag,
            surface_recorder=editing,
            next_tag=self.project.next_surface_recorder_tag(),
            parent=self,
        )
        if not dialog.exec():
            return
        surface_recorder = dialog.data()

        before = self.project.to_dict()
        try:
            if editing is None:
                self.project.add_surface_recorder(surface_recorder)
                generated_tag = sync_surface_recorder(
                    self.project,
                    surface_recorder.tag,
                )
            else:
                surface_recorder.generated_recorder_tag = (
                    editing.generated_recorder_tag
                )
                generated_tag = replace_surface_recorder(
                    self.project,
                    surface_recorder,
                )
        except (TypeError, ValueError, IndexError) as exc:
            self.project = ProjectDatabase.from_dict(before)
            self.model = self.project.model
            self._refresh_all()
            QMessageBox.warning(
                self,
                "Managed Surface Shell Recorder",
                str(exc),
            )
            return

        self.model = self.project.model
        self._refresh_all(
            f"{'Updated' if editing is not None else 'Created'} managed "
            f"Surface Shell recorder {surface_recorder.tag} · "
            f"generated recorder {generated_tag} targets "
            f"{len(self.project.recorders[generated_tag].target_tags)} "
            "Shell element(s)"
        )
        self.viewport.set_display_domain("geometry")
        self._show_surface_geometry_properties(tag)
        self._record_project_change(
            f"Managed Surface Shell recorder {surface_recorder.tag}",
            before,
        )

    def _select_managed_surface_recorder_targets(
        self,
        surface_tag: int,
    ) -> None:
        tag = int(surface_tag)
        definitions = sorted(
            (
                recorder
                for recorder in self.project.surface_recorders.values()
                if recorder.surface_tag == tag
            ),
            key=lambda item: item.tag,
        )
        if not definitions:
            QMessageBox.information(
                self,
                "Managed Surface Shell Recorder",
                f"Surface {tag} has no managed Shell recorder.",
            )
            return
        labels = [
            f"Recorder {item.tag} · {item.response} · GP "
            f"{item.section_number}"
            for item in definitions
        ]
        label, ok = QInputDialog.getItem(
            self,
            "Select Recorder FE Targets",
            f"Surface {tag}:",
            labels,
            0,
            False,
        )
        if not ok:
            return
        definition = definitions[labels.index(label)]
        generated_tag = definition.generated_recorder_tag
        recorder = (
            self.project.recorders.get(int(generated_tag))
            if generated_tag is not None
            else None
        )
        if recorder is None:
            if not self._ask_create_prerequisite(
                title="Select Recorder FE Targets",
                message=(
                    "The managed recorder currently has no live FE "
                    "realization. Mesh/remesh the Surface and rebuild the "
                    "recorder now?"
                ),
                action_label="Mesh + Rebuild Recorder Now...",
            ):
                return
            if not self._ensure_surface_meshes(
                [tag],
                title="Select Recorder FE Targets",
            ):
                return
            try:
                generated_tag = sync_surface_recorder(
                    self.project,
                    definition.tag,
                )
            except (TypeError, ValueError, IndexError) as exc:
                QMessageBox.warning(
                    self,
                    "Select Recorder FE Targets",
                    str(exc),
                )
                return
            recorder = self.project.recorders.get(int(generated_tag))
            if recorder is None:
                return
            self.model = self.project.model
            self._refresh_all(
                f"Rebuilt managed Surface recorder {definition.tag}"
            )

        self.viewport.set_display_domain("fe")
        self.selection.set_selection(
            elements=set(recorder.target_tags),
        )
        self.status_message.setText(
            f"Selected {len(recorder.target_tags)} Shell target(s) for "
            f"managed Surface recorder {definition.tag}"
        )

    def _remove_managed_surface_shell_recorder(
        self,
        surface_tag: int,
        *,
        recorder_tag: int | None = None,
    ) -> None:
        tag = int(surface_tag)
        definitions = sorted(
            (
                recorder
                for recorder in self.project.surface_recorders.values()
                if recorder.surface_tag == tag
            ),
            key=lambda item: item.tag,
        )
        if not definitions:
            QMessageBox.information(
                self,
                "Remove Managed Surface Shell Recorder",
                f"Surface {tag} has no managed Shell recorder.",
            )
            return
        target = next(
            (
                item
                for item in definitions
                if recorder_tag is not None
                and item.tag == int(recorder_tag)
            ),
            None,
        )
        if target is not None:
            definition = target
        else:
            labels = [
                f"Recorder {item.tag} · {item.response} · GP "
                f"{item.section_number} · {item.file_name}"
                for item in definitions
            ]
            label, ok = QInputDialog.getItem(
                self,
                "Remove Managed Surface Shell Recorder",
                f"Surface {tag}:",
                labels,
                0,
                False,
            )
            if not ok:
                return
            definition = definitions[labels.index(label)]

        before = self.project.to_dict()
        try:
            generated_tag = remove_surface_recorder(
                self.project,
                definition.tag,
            )
        except ValueError as exc:
            self.project = ProjectDatabase.from_dict(before)
            self.model = self.project.model
            self._refresh_all()
            QMessageBox.warning(
                self,
                "Remove Managed Surface Shell Recorder",
                str(exc),
            )
            return

        self.model = self.project.model
        self._refresh_all(
            f"Removed managed Surface recorder {definition.tag}"
            + (
                f" and generated recorder {generated_tag}"
                if generated_tag is not None
                else ""
            )
        )
        self.viewport.set_display_domain("geometry")
        self._show_surface_geometry_properties(tag)
        self._record_project_change(
            f"Remove managed Surface recorder {definition.tag}",
            before,
        )

    def _compatible_surface_result_analyses(self):
        return {
            int(tag): analysis
            for tag, analysis in self.project.analyses.items()
            if (
                "ShellForce"
                in self.project._allowed_solution_result_types(analysis)
                and "ShellDeformation"
                in self.project._allowed_solution_result_types(analysis)
            )
        }

    def _manage_surface_shell_result(
        self,
        surface_tags,
        *,
        result_tag: int | None = None,
    ) -> None:
        tags = sorted({
            int(tag)
            for tag in surface_tags
            if int(tag) in self.project.surfaces
        })
        if not tags:
            return

        if not self._ensure_surface_meshes(
            tags,
            title="Managed Surface Shell Result",
        ):
            return

        analyses = self._compatible_surface_result_analyses()
        if not analyses:
            if not self._ensure_prerequisite(
                title="Managed Surface Shell Result",
                message=(
                    "Shell result requests require compatible Analysis "
                    "Settings. Create them now?"
                ),
                action_label="Create Analysis Settings Now...",
                available=lambda: bool(
                    self._compatible_surface_result_analyses()
                ),
                creator=self._create_analysis,
            ):
                return
            analyses = self._compatible_surface_result_analyses()
            if not analyses:
                return

        target_scope = set(tags)
        existing = sorted(
            (
                result
                for result in self.project.solution_results.values()
                if (
                    result.surface_scope
                    and set(result.surface_scope) == target_scope
                    and result.result_type
                    in {"ShellForce", "ShellDeformation", "ShellDisplacement"}
                )
            ),
            key=lambda item: item.tag,
        )
        target = next(
            (
                item
                for item in existing
                if result_tag is not None
                and item.tag == int(result_tag)
            ),
            None,
        )
        if target is not None:
            editing = target
        else:
            choices = ["Create new result..."] + [
                f"Edit Result {item.tag} · {item.result_type} · "
                f"{item.settings.get('component', '')}"
                for item in existing
            ]
            choice, ok = QInputDialog.getItem(
                self,
                "Managed Surface Shell Result",
                "Definition:",
                choices,
                0,
                False,
            )
            if not ok:
                return
            editing = (
                None if choice == choices[0]
                else existing[choices.index(choice) - 1]
            )

        dialog = SurfaceResultDialog(
            analyses,
            surface_tags=(
                editing.surface_scope
                if editing is not None
                else tags
            ),
            result=editing,
            next_tag=self.project.next_solution_result_tag(),
            new_analysis_callback=self._create_analysis_dependency,
            parent=self,
        )
        if not dialog.exec():
            return
        result = dialog.data()

        before = self.project.to_dict()
        try:
            if editing is None:
                self.project.add_solution_result(result)
            else:
                self.project.update_solution_result(
                    editing.tag,
                    result,
                )
        except (TypeError, ValueError) as exc:
            self.project = ProjectDatabase.from_dict(before)
            self.model = self.project.model
            self._refresh_all()
            QMessageBox.warning(
                self,
                "Managed Surface Shell Result",
                str(exc),
            )
            return

        self.model = self.project.model
        self._refresh_all(
            f"{'Updated' if editing is not None else 'Created'} managed "
            f"Shell result {result.tag} · {len(result.surface_scope)} "
            f"Surface(s) · {len(result.element_scope)} Shell element(s)"
        )
        self.viewport.set_display_domain("geometry")
        self._show_surface_geometry_properties(tags[0])
        self._record_project_change(
            f"Managed Surface Shell result {result.tag}",
            before,
        )

    def _managed_surface_results_for_surface(
        self,
        surface_tag: int,
    ) -> list[SolutionResultData]:
        tag = int(surface_tag)
        return sorted(
            (
                result
                for result in self.project.solution_results.values()
                if (
                    tag in result.surface_scope
                    and result.result_type
                    in {"ShellForce", "ShellDeformation", "ShellDisplacement"}
                )
            ),
            key=lambda item: item.tag,
        )

    def _select_managed_surface_result_scope(
        self,
        surface_tag: int,
    ) -> None:
        tag = int(surface_tag)
        results = self._managed_surface_results_for_surface(tag)
        if not results:
            QMessageBox.information(
                self,
                "Managed Surface Shell Result",
                f"Surface {tag} has no managed Shell result request.",
            )
            return
        labels = [
            f"Result {result.tag} · {result.result_type} · "
            f"{result.settings.get('component', '')}"
            for result in results
        ]
        label, ok = QInputDialog.getItem(
            self,
            "Select Managed Result FE Scope",
            f"Surface {tag}:",
            labels,
            0,
            False,
        )
        if not ok:
            return
        result = results[labels.index(label)]
        self.viewport.set_display_domain("fe")
        self.selection.set_selection(
            elements=set(result.element_scope),
        )
        self.status_message.setText(
            f"Selected {len(result.element_scope)} Shell element(s) for "
            f"managed result {result.tag}"
        )

    def _remove_managed_surface_shell_result(
        self,
        surface_tag: int,
    ) -> None:
        tag = int(surface_tag)
        results = self._managed_surface_results_for_surface(tag)
        if not results:
            QMessageBox.information(
                self,
                "Remove Managed Surface Shell Result",
                f"Surface {tag} has no managed Shell result request.",
            )
            return
        labels = [
            f"Result {result.tag} · {result.result_type} · "
            f"{result.settings.get('component', '')} · "
            f"{len(result.surface_scope)} Surface(s)"
            for result in results
        ]
        label, ok = QInputDialog.getItem(
            self,
            "Remove Managed Surface Shell Result",
            f"Surface {tag}:",
            labels,
            0,
            False,
        )
        if not ok:
            return
        result = results[labels.index(label)]
        before = self.project.to_dict()
        if len(result.surface_scope) == 1:
            self.project.remove_solution_result(result.tag)
            message = f"Removed managed Shell result {result.tag}"
        else:
            updated = SolutionResultData(
                tag=result.tag,
                analysis_tag=result.analysis_tag,
                name=result.name,
                result_type=result.result_type,
                node_scope=list(result.node_scope),
                element_scope=list(result.element_scope),
                surface_scope=[
                    item
                    for item in result.surface_scope
                    if int(item) != tag
                ],
                settings=dict(result.settings),
            )
            try:
                self.project.update_solution_result(
                    result.tag,
                    updated,
                )
            except (TypeError, ValueError) as exc:
                self.project = ProjectDatabase.from_dict(before)
                self.model = self.project.model
                self._refresh_all()
                QMessageBox.warning(
                    self,
                    "Remove Managed Surface Shell Result",
                    str(exc),
                )
                return
            message = (
                f"Removed Surface {tag} from managed Shell result "
                f"{result.tag}"
            )

        self.model = self.project.model
        self._refresh_all(message)
        self.viewport.set_display_domain("geometry")
        self._show_surface_geometry_properties(tag)
        self._record_project_change(
            f"Update managed Surface Shell result {result.tag}",
            before,
        )

    def _create_shell_pressure_for_elements(
        self,
        selected,
        *,
        source_label: str | None = None,
    ) -> None:
        selected = sorted({
            int(tag)
            for tag in selected
            if (
                int(tag) in self.model.elements
                and self.model.elements[
                    int(tag)
                ].element_type in SHELL_ELEMENT_TYPES
            )
        })
        if not selected:
            return

        plain = self._plain_load_patterns()
        if not plain:
            if not self._ensure_plain_load_pattern(
                title="Shell Surface Pressure"
            ):
                return
            plain = self._plain_load_patterns()

        dialog = ElementLoadDialog(
            plain,
            next_tag=self.project.next_element_load_tag(),
            element_tag=selected[0],
            units=self.project.units,
            allowed_load_types={"SurfacePressure"},
            new_pattern_callback=self._create_plain_pattern_dependency,
            parent=self,
        )
        if not dialog.exec():
            return

        template = dialog.data()
        before = self.project.to_dict()
        created: list[int] = []
        next_tag = template.tag
        try:
            for element_tag in selected:
                while next_tag in self.project.element_loads:
                    next_tag += 1
                load = ElementLoadData(
                    tag=next_tag,
                    name=(
                        f"{template.name} - Shell {element_tag}"
                        if len(selected) > 1
                        else template.name
                    ),
                    pattern_tag=template.pattern_tag,
                    element_tag=element_tag,
                    load_type="SurfacePressure",
                    pressure=template.pressure,
                )
                self.project.add_element_load(load)
                created.append(load.tag)
                next_tag += 1
        except ValueError as exc:
            self.project = ProjectDatabase.from_dict(before)
            self.model = self.project.model
            QMessageBox.warning(
                self,
                "Shell Surface Pressure",
                str(exc),
            )
            self._refresh_all()
            return

        label = f" on {source_label}" if source_label else ""
        self._refresh_project_metadata(
            f"Created {len(created)} shell surface pressure load(s){label}"
        )
        self._record_project_change(
            "Create shell surface pressure load(s)",
            before,
        )

    def _create_shell_pressure(self) -> None:
        selected = sorted(
            int(tag)
            for tag in self.selection.elements
            if (
                tag in self.model.elements
                and self.model.elements[tag].element_type
                in SHELL_ELEMENT_TYPES
            )
        )
        if not selected:
            existing = sorted(
                int(tag)
                for tag, element in self.model.elements.items()
                if element.element_type in SHELL_ELEMENT_TYPES
            )
            if not existing:
                if not self._ensure_prerequisite(
                    title="Shell Surface Pressure",
                    message=(
                        "Surface pressure requires meshed Shell elements. "
                        "Create one now?"
                    ),
                    action_label="Create & Mesh Surface Now...",
                    available=lambda: any(
                        element.element_type in SHELL_ELEMENT_TYPES
                        for element in self.model.elements.values()
                    ),
                    creator=self._create_surface_geometry_and_mesh,
                ):
                    return
                selected = sorted(
                    int(tag)
                    for tag in self.selection.elements
                    if (
                        tag in self.model.elements
                        and self.model.elements[tag].element_type
                        in SHELL_ELEMENT_TYPES
                    )
                )
            else:
                QMessageBox.information(
                    self,
                    "Shell Surface Pressure",
                    "Select at least one Shell element first, or use "
                    "Geometry → Surface → Managed Surface Pressure...",
                )
                return
        if selected:
            self._create_shell_pressure_for_elements(selected)

    def _create_element_load(self) -> None:
        plain = self._plain_load_patterns()
        if not plain:
            if not self._ensure_plain_load_pattern(
                title="Beam / Element Load"
            ):
                return
            plain = self._plain_load_patterns()

        selected_tags = self._selected_element_tags(
            "Beam / Element Load",
            create_if_missing=True,
            frame_only=True,
        )
        if selected_tags is None:
            return
        selected = sorted(selected_tags)

        dialog = ElementLoadDialog(
            plain,
            next_tag=self.project.next_element_load_tag(),
            element_tag=selected[0],
            units=self.project.units,
            allowed_load_types={
                "Uniform", "Triangular", "Trapezoidal", "Point", "SelfWeight"
            },
            new_pattern_callback=self._create_plain_pattern_dependency,
            parent=self,
        )
        if not dialog.exec():
            return

        template = dialog.data()
        before = self.project.to_dict()
        created: list[int] = []
        next_tag = template.tag
        try:
            for element_tag in selected:
                while next_tag in self.project.element_loads:
                    next_tag += 1
                load = ElementLoadData(
                    tag=next_tag,
                    name=(
                        f"{template.name} - Element {element_tag}"
                        if len(selected) > 1
                        else template.name
                    ),
                    pattern_tag=template.pattern_tag,
                    element_tag=element_tag,
                    load_type=template.load_type,
                    wx=template.wx,
                    wy=template.wy,
                    wz=template.wz,
                    px=template.px,
                    py=template.py,
                    pz=template.pz,
                    x_over_l=template.x_over_l,
                    gravity=template.gravity,
                    density_override=template.density_override,
                    pressure=template.pressure,
                    coordinate_system=template.coordinate_system,
                    wx_end=template.wx_end,
                    wy_end=template.wy_end,
                    wz_end=template.wz_end,
                    a_over_l=template.a_over_l,
                    b_over_l=template.b_over_l,
                )
                self.project.add_element_load(load)
                created.append(load.tag)
                next_tag += 1
        except ValueError as exc:
            self.project = ProjectDatabase.from_dict(before)
            self.model = self.project.model
            QMessageBox.warning(
                self,
                "Beam / Element Load Editor",
                str(exc),
            )
            self._refresh_all()
            return

        self._refresh_project_metadata(
            f"Created {len(created)} element load(s)"
        )
        self._record_project_change(
            "Create element load(s)",
            before,
        )

    def _managed_surface_pressure_for_element_load(
        self,
        element_load_tag: int,
    ) -> SurfacePressureData | None:
        target = int(element_load_tag)
        for pressure in self.project.surface_pressures.values():
            if target in pressure.generated_element_load_tags:
                return pressure
        return None

    def _edit_element_load(self, tag: int) -> None:
        load = self.project.element_loads.get(tag)
        if load is None:
            return
        owner = self._managed_surface_pressure_for_element_load(tag)
        if owner is not None:
            if self._ask_create_prerequisite(
                title="Managed Surface Pressure",
                message=(
                    "This element load is generated by managed Surface "
                    f"Pressure {owner.tag} on Surface {owner.surface_tag}. "
                    "Open its managed definition now?"
                ),
                action_label="Edit Managed Pressure Now...",
            ):
                self._create_surface_pressure_for_surfaces(
                    [owner.surface_tag],
                    pressure_tag=owner.tag,
                )
            return
        plain = {
            key: pattern
            for key, pattern in self.project.load_patterns.items()
            if pattern.pattern_type == "Plain"
        }
        dialog = ElementLoadDialog(
            plain,
            load=load,
            units=self.project.units,
            new_pattern_callback=self._create_plain_pattern_dependency,
            parent=self,
        )
        if not dialog.exec():
            return
        before = self.project.to_dict()
        try:
            updated = dialog.data()
            self.project.update_element_load(tag, updated)
        except ValueError as exc:
            QMessageBox.warning(
                self,
                "Beam / Element Load Editor",
                str(exc),
            )
            return
        self._refresh_project_metadata(
            f"Updated element load {updated.tag}"
        )
        self._show_element_load_properties(updated.tag)
        self._record_project_change(
            f"Edit element load {tag}",
            before,
        )

    def _delete_element_load(self, tag: int) -> None:
        if tag not in self.project.element_loads:
            return
        owner = self._managed_surface_pressure_for_element_load(tag)
        if owner is not None:
            if self._ask_create_prerequisite(
                title="Managed Surface Pressure",
                message=(
                    "This element load is generated by managed Surface "
                    f"Pressure {owner.tag}. Remove the managed pressure "
                    "definition instead?"
                ),
                action_label="Remove Managed Pressure Now...",
            ):
                self._remove_managed_surface_pressure(
                    owner.surface_tag,
                    pressure_tag=owner.tag,
                )
            return
        before = self.project.to_dict()
        self.project.remove_element_load(tag)
        self._refresh_project_metadata(
            f"Deleted element load {tag}"
        )
        self._record_project_change(
            f"Delete element load {tag}",
            before,
        )

    def _show_element_load_properties(self, tag: int) -> None:
        load = self.project.element_loads.get(tag)
        if load is None:
            return
        rows: list[tuple[str, object]] = [
            ("Tag", load.tag),
            ("Name", load.name),
            ("Pattern", load.pattern_tag),
            ("Element", load.element_tag),
            ("Type", load.load_type),
        ]
        if load.load_type in {"Uniform", "Triangular", "Trapezoidal"}:
            coordinate = (
                "Global XYZ"
                if load.coordinate_system == "global"
                else "Local xyz"
            )
            axis_prefix = (
                "Global" if load.coordinate_system == "global" else "Local"
            )
            start_prefix = (
                axis_prefix
                if load.load_type == "Uniform"
                else f"Start {axis_prefix}"
            )
            rows.extend([
                ("Coordinate System", coordinate),
                (f"{start_prefix} X", f"{load.wx:g}"),
                (f"{start_prefix} Y", f"{load.wy:g}"),
                (f"{start_prefix} Z", f"{load.wz:g}"),
            ])
            if load.load_type in {"Triangular", "Trapezoidal"}:
                rows.extend([
                    (f"End {axis_prefix} X", f"{load.wx_end:g}"),
                    (f"End {axis_prefix} Y", f"{load.wy_end:g}"),
                    (f"End {axis_prefix} Z", f"{load.wz_end:g}"),
                    ("Start a/L", f"{load.a_over_l:g}"),
                    ("End b/L", f"{load.b_over_l:g}"),
                ])
        elif load.load_type == "Point":
            coordinate = (
                "Global XYZ"
                if load.coordinate_system == "global"
                else "Local xyz"
            )
            axis_prefix = "Global" if load.coordinate_system == "global" else "Local"
            rows.extend([
                ("Coordinate System", coordinate),
                (f"{axis_prefix} X", f"{load.px:g}"),
                (f"{axis_prefix} Y", f"{load.py:g}"),
                (f"{axis_prefix} Z", f"{load.pz:g}"),
                ("x/L along member", f"{load.x_over_l:g}"),
            ])
        elif load.load_type == "SurfacePressure":
            unit_system = UnitSystem.from_mapping(self.project.units)
            element = self.model.elements.get(load.element_tag)
            try:
                _center, normal, _area = shell_surface_geometry(
                    self.model,
                    element,
                )
                pressure_vector = tuple(
                    float(load.pressure) * float(value)
                    for value in normal
                )
                normal_text = "(" + ", ".join(
                    f"{value:.6g}" for value in normal
                ) + ")"
                pressure_vector_text = "(" + ", ".join(
                    f"{value:.6g}" for value in pressure_vector
                ) + ")"
            except (TypeError, ValueError):
                normal_text = "Unavailable"
                pressure_vector_text = "Unavailable"
            rows.extend([
                (
                    f"Pressure [{unit_system.stress_label}]",
                    f"{load.pressure:g}",
                ),
                (
                    "Direction",
                    "Shell normal: + outward / - inward",
                ),
                ("Shell normal XYZ", normal_text),
                (
                    f"Global pressure vector [{unit_system.stress_label}]",
                    pressure_vector_text,
                ),
                (
                    "OpenSees",
                    "SurfaceLoad + eleLoad -surfaceLoad",
                ),
            ])
        else:
            rows.extend([
                ("Gravity", ", ".join(
                    f"{value:g}" for value in load.gravity
                )),
                (
                    "Density override",
                    (
                        f"{load.density_override:g}"
                        if load.density_override > 0.0
                        else "Linked material"
                    ),
                ),
            ])
        self.properties_panel.set_properties(
            "Beam / Element Load",
            rows,
        )

    def _selected_element_tags(
        self,
        title: str,
        *,
        create_if_missing: bool = False,
        frame_only: bool = False,
    ) -> set[int] | None:
        frame_types = set(FRAME_ELEMENT_TYPES)

        def eligible(tag: int) -> bool:
            element = self.model.elements.get(int(tag))
            if element is None:
                return False
            return not frame_only or element.element_type in frame_types

        tags = {
            int(tag)
            for tag in self.selection.elements
            if eligible(int(tag))
        }
        if tags:
            return tags

        available = {
            int(tag)
            for tag in self.model.elements
            if eligible(int(tag))
        }
        if create_if_missing and not available:
            if not self._ensure_prerequisite(
                title=title,
                message=(
                    "This workflow requires a beam-column element first. "
                    "Create a Frame member now?"
                ),
                action_label="Create Frame Now...",
                available=lambda: any(
                    element.element_type in frame_types
                    for element in self.model.elements.values()
                ),
                creator=self._create_frame,
            ):
                return None
            tags = {
                int(tag)
                for tag in self.selection.elements
                if eligible(int(tag))
            }
            if tags:
                return tags

        QMessageBox.information(
            self,
            title,
            (
                "Select at least one beam-column element first."
                if frame_only
                else "Select at least one element first."
            ),
        )
        return None

    def _set_element_formulation(self) -> None:
        element_tags = self._selected_element_tags(
            "Element Formulation",
            create_if_missing=True,
            frame_only=True,
        )
        if element_tags is None:
            return

        selected = [
            self.model.elements[tag]
            for tag in sorted(element_tags)
            if tag in self.model.elements
        ]
        first = selected[0]
        same_type = all(
            element.element_type == first.element_type
            for element in selected
        )
        same_integration = all(
            (
                element.integration_type,
                element.integration_points,
                element.force_max_iter,
                element.force_tolerance,
                element.mass_per_length,
                element.consistent_mass,
                element.beam_center_ratio,
            )
            == (
                first.integration_type,
                first.integration_points,
                first.force_max_iter,
                first.force_tolerance,
                first.mass_per_length,
                first.consistent_mass,
                first.beam_center_ratio,
            )
            for element in selected
        )

        dialog = ElementFormulationDialog(
            element_type=(
                first.element_type
                if same_type and first.element_type
                in FRAME_ELEMENT_TYPES
                else "elasticBeamColumn"
            ),
            integration_type=(
                first.integration_type
                if same_integration
                else "Lobatto"
            ),
            integration_points=(
                first.integration_points
                if same_integration
                else 5
            ),
            force_max_iter=(
                first.force_max_iter
                if same_integration
                else 10
            ),
            force_tolerance=(
                first.force_tolerance
                if same_integration
                else 1.0e-12
            ),
            mass_per_length=(
                first.mass_per_length
                if same_integration
                else 0.0
            ),
            consistent_mass=(
                first.consistent_mass
                if same_integration
                else False
            ),
            beam_center_ratio=(
                first.beam_center_ratio
                if same_integration
                else 0.4
            ),
            ndm=self.model.ndm,
            ndf=self.model.ndf,
            units=self.project.units,
            parent=self,
        )
        if not dialog.exec():
            return

        before = self.project.to_dict()
        try:
            updated = self.project.assign_element_formulation(
                element_tags,
                **dialog.values(),
            )
        except ValueError as exc:
            QMessageBox.warning(
                self,
                "Element Formulation",
                str(exc),
            )
            return

        self._refresh_project_metadata(
            f"Updated formulation for {len(updated)} element(s)"
        )
        self._record_project_change(
            "Set element formulation",
            before,
        )

    def _assign_section_to_selection(self) -> None:
        selected_tags = self._selected_element_tags(
            "Assign Section",
            create_if_missing=True,
        )
        if selected_tags is None:
            return
        element_tags = {
            int(tag)
            for tag in selected_tags
            if (
                int(tag) in self.model.elements
                and self.model.elements[int(tag)].element_type
                in (FRAME_ELEMENT_TYPES | TRUSS_SECTION_ELEMENT_TYPES)
            )
        }
        if not element_tags:
            QMessageBox.information(
                self,
                "Assign Section",
                "Select at least one frame or section-based Truss element.",
            )
            return
        if not self._ensure_prerequisite(
            title="Assign Section",
            message=(
                "No Sections exist yet. Create a Section now, then return "
                "directly to assignment?"
            ),
            action_label="Create Section Now...",
            available=lambda: bool(self.project.sections),
            creator=self._create_section,
        ):
            return

        def compatible(section) -> bool:
            section_type = str(section.section_type)
            for element_tag in element_tags:
                element = self.model.elements[element_tag]
                if (
                    element.element_type in TRUSS_SECTION_ELEMENT_TYPES
                    and section_type not in {"Elastic", "Fiber", "FiberInt"}
                ):
                    return False
                if (
                    element.element_type
                    in {"elasticBeamColumn", "ElasticTimoshenkoBeam"}
                    and section_type != "Elastic"
                ):
                    return False
                if (
                    element.element_type == "dispBeamColumnInt"
                    and section_type != "FiberInt"
                ):
                    return False
            return True

        tags = [
            int(tag)
            for tag, section in sorted(self.project.sections.items())
            if compatible(section)
        ]
        if not tags:
            QMessageBox.information(
                self,
                "Assign Section",
                "No Section is compatible with all selected elements.",
            )
            return
        labels = [
            (
                f"{tag} - {self.project.sections[tag].name} "
                f"({self.project.sections[tag].section_type})"
            )
            for tag in tags
        ]
        label, ok = QInputDialog.getItem(
            self,
            "Assign Section",
            f"Assign to {len(element_tags)} selected element(s):",
            labels,
            0,
            False,
        )
        if not ok:
            return
        section_tag = tags[labels.index(label)]

        before = self.project.to_dict()
        try:
            assigned = self.project.assign_section_to_elements(
                element_tags,
                section_tag,
            )
        except ValueError as exc:
            QMessageBox.warning(self, "Assign Section", str(exc))
            return
        self._refresh_project_metadata(
            f"Assigned section {section_tag} to {len(assigned)} element(s)"
        )
        self._record_project_change(
            f"Assign section {section_tag}",
            before,
        )

    def _assign_truss_material_to_selection(self) -> None:
        if not any(
            element.element_type in TRUSS_MATERIAL_ELEMENT_TYPES
            for element in self.model.elements.values()
        ):
            if not self._ensure_prerequisite(
                title="Assign Truss Material",
                message=(
                    "No Truss element exists yet. Create a Truss now, then "
                    "return directly to material assignment?"
                ),
                action_label="Create Truss Now...",
                available=lambda: any(
                    element.element_type in TRUSS_MATERIAL_ELEMENT_TYPES
                    for element in self.model.elements.values()
                ),
                creator=self._create_truss,
            ):
                return
        element_tags = self._selected_element_tags(
            "Assign Truss Material"
        )
        if element_tags is None:
            return
        truss_tags = {
            tag
            for tag in element_tags
            if tag in self.model.elements
            and self.model.elements[tag].element_type in TRUSS_MATERIAL_ELEMENT_TYPES
        }
        if not truss_tags:
            QMessageBox.information(
                self,
                "Assign Truss Material",
                "Select at least one Truss element first.",
            )
            return
        if not self._ensure_prerequisite(
            title="Assign Truss Material",
            message=(
                "No uniaxial Materials exist yet. Create a Material now, "
                "then return directly to assignment?"
            ),
            action_label="Create Material Now...",
            available=lambda: bool(self.project.materials),
            creator=self._create_material,
        ):
            return

        tags = sorted(self.project.materials)
        labels = [
            (
                f"{tag} - {self.project.materials[tag].name} "
                f"({self.project.materials[tag].material_type})"
            )
            for tag in tags
        ]
        existing = {
            self.model.elements[tag].truss_material_tag
            for tag in truss_tags
        }
        current_index = 0
        if len(existing) == 1:
            current_tag = next(iter(existing))
            if current_tag in tags:
                current_index = tags.index(current_tag)

        label, ok = QInputDialog.getItem(
            self,
            "Assign Truss Material",
            f"Assign to {len(truss_tags)} selected Truss element(s):",
            labels,
            current_index,
            False,
        )
        if not ok:
            return
        material_tag = tags[labels.index(label)]

        before = self.project.to_dict()
        assigned = self.model.assign_truss_material(
            truss_tags,
            material_tag,
        )
        self._refresh_project_metadata(
            f"Assigned material {material_tag} to "
            f"{len(assigned)} Truss element(s)"
        )
        self._record_project_change(
            f"Assign Truss material {material_tag}",
            before,
        )

