    def _copy_line_mesh_recipe_to_selected(
        self,
        source_tag: int,
        target_tags,
    ) -> None:
        source_tag = int(source_tag)
        targets = sorted({
            int(tag)
            for tag in target_tags
            if int(tag) in self.project.lines and int(tag) != source_tag
        })
        if not targets and len(self.project.lines) < 2:
            if not self._ensure_geometry_line_count(
                2,
                title="Copy Line Mesh / FE Recipe",
            ):
                return
            targets = sorted(
                tag
                for tag in self.project.lines
                if int(tag) != source_tag
            )
        if not targets:
            QMessageBox.information(
                self,
                "Copy Line Mesh / FE Recipe",
                "Select one or more additional Geometry Lines first. "
                "The right-clicked Line is used as the source recipe.",
            )
            return
        before = self.project.to_dict()
        try:
            results = copy_line_mesh_recipe(
                self.project,
                source_tag,
                targets,
                remesh_live=True,
            )
        except (TypeError, ValueError) as exc:
            self.project = ProjectDatabase.from_dict(before)
            self.model = self.project.model
            self._refresh_all()
            QMessageBox.warning(
                self,
                "Copy Line Mesh / FE Recipe",
                str(exc),
            )
            return
        self.model = self.project.model
        remeshed = sum(result is not None for result in results.values())
        self._refresh_all(
            f"Copied Line {source_tag} mesh / FE recipe to "
            f"{len(targets)} Line(s) · {remeshed} remeshed"
        )
        self.selection.clear()
        self.viewport.set_display_domain("geometry")
        self._record_project_change(
            f"Copy Geometry Line {source_tag} mesh / FE recipe",
            before,
        )

    def _remesh_line_geometries(self, line_tags) -> None:
        tags = sorted({
            int(tag)
            for tag in line_tags
            if int(tag) in self.project.lines
        })
        if not tags:
            return
        before = self.project.to_dict()
        try:
            results = remesh_line_batch(self.project, tags)
        except (TypeError, ValueError) as exc:
            self.project = ProjectDatabase.from_dict(before)
            self.model = self.project.model
            self._refresh_all()
            QMessageBox.warning(self, "Batch Line Mesh", str(exc))
            return
        self.model = self.project.model
        element_count = sum(
            len(result.element_tags)
            for result in results.values()
        )
        self._refresh_all(
            f"Generated / remeshed {len(tags)} Line(s) · "
            f"{element_count} Frame/Truss element(s)"
        )
        self.selection.clear()
        self.viewport.set_display_domain("geometry")
        self._record_project_change(
            "Batch mesh Geometry Lines "
            + ", ".join(map(str, tags)),
            before,
        )

    def _split_selected_geometry_lines_at_intersection(self) -> None:
        tags = self._selected_line_geometry_tags()
        if len(tags) != 2 and len(self.project.lines) < 2:
            if not self._ensure_geometry_line_count(
                2,
                title="Split by Line",
            ):
                return
            tags = sorted(self.project.lines)[:2]
        if len(tags) != 2:
            QMessageBox.information(
                self,
                "Split by Line",
                "Select exactly two intersecting Geometry Lines.",
            )
            return
        before = self.project.to_dict()
        try:
            result = split_line_pair_at_intersection(
                self.project,
                tags[0],
                tags[1],
                remesh=True,
            )
        except (TypeError, ValueError) as exc:
            self.project = ProjectDatabase.from_dict(before)
            self.model = self.project.model
            self._refresh_all()
            QMessageBox.warning(self, "Split by Line", str(exc))
            return
        self.model = self.project.model
        self._refresh_all(
            f"Split Lines {tags[0]} / {tags[1]} at "
            f"Point {result.intersection_point_tag} · "
            f"{len(result.created_line_tags)} new Line segment(s)"
        )
        self.selection.clear()
        self.viewport.set_display_domain("geometry")
        self._record_project_change(
            f"Split Geometry Lines {tags[0]} / {tags[1]} at intersection",
            before,
        )

    def _fillet_selected_geometry_lines(self) -> None:
        tags = self._selected_line_geometry_tags()
        if len(tags) != 2 and len(self.project.lines) < 2:
            if not self._ensure_geometry_line_count(
                2,
                title="Fillet Geometry Lines",
            ):
                return
            tags = sorted(self.project.lines)[:2]
        if len(tags) != 2:
            QMessageBox.information(
                self,
                "Fillet Geometry Lines",
                "Select exactly two connected Geometry Lines.",
            )
            return
        radius, ok = QInputDialog.getDouble(
            self,
            "Fillet Geometry Lines",
            (
                "Fillet radius. Current straight-Line kernel represents the "
                "arc as 8 tangent Line segments:"
            ),
            0.1,
            1.0e-12,
            1.0e12,
            8,
        )
        if not ok:
            return
        before = self.project.to_dict()
        try:
            result = fillet_lines(
                self.project,
                tags[0],
                tags[1],
                radius=radius,
                segments=8,
                remesh=True,
            )
        except (TypeError, ValueError) as exc:
            self.project = ProjectDatabase.from_dict(before)
            self.model = self.project.model
            self._refresh_all()
            QMessageBox.warning(self, "Fillet Geometry Lines", str(exc))
            return
        self.model = self.project.model
        self._refresh_all(
            f"Fillet Lines {tags[0]} / {tags[1]} · R={radius:g} · "
            f"{len(result.connector_line_tags)} tangent segment(s)"
        )
        self.selection.clear()
        self.viewport.set_display_domain("geometry")
        self._record_project_change(
            f"Fillet Geometry Lines {tags[0]} / {tags[1]}",
            before,
        )

    def _chamfer_selected_geometry_lines(self) -> None:
        tags = self._selected_line_geometry_tags()
        if len(tags) != 2 and len(self.project.lines) < 2:
            if not self._ensure_geometry_line_count(
                2,
                title="Chamfer Geometry Lines",
            ):
                return
            tags = sorted(self.project.lines)[:2]
        if len(tags) != 2:
            QMessageBox.information(
                self,
                "Chamfer Geometry Lines",
                "Select exactly two connected Geometry Lines.",
            )
            return
        distance, ok = QInputDialog.getDouble(
            self,
            "Chamfer Geometry Lines",
            "Equal setback distance along both Lines:",
            0.1,
            1.0e-12,
            1.0e12,
            8,
        )
        if not ok:
            return
        before = self.project.to_dict()
        try:
            result = chamfer_lines(
                self.project,
                tags[0],
                tags[1],
                distance=distance,
                remesh=True,
            )
        except (TypeError, ValueError) as exc:
            self.project = ProjectDatabase.from_dict(before)
            self.model = self.project.model
            self._refresh_all()
            QMessageBox.warning(self, "Chamfer Geometry Lines", str(exc))
            return
        self.model = self.project.model
        self._refresh_all(
            f"Chamfer Lines {tags[0]} / {tags[1]} · "
            f"setback={distance:g}"
        )
        self.selection.clear()
        self.viewport.set_display_domain("geometry")
        self._record_project_change(
            f"Chamfer Geometry Lines {tags[0]} / {tags[1]}",
            before,
        )

    def _split_selected_geometry_line(self) -> None:
        tags = self._selected_line_geometry_tags()
        if len(tags) != 1:
            QMessageBox.information(
                self,
                "Split / Divide Geometry Line",
                "Select exactly one Geometry Line, then run Split / Divide.",
            )
            return
        self._divide_geometry_line(tags[0])

    def _join_selected_geometry_lines(self) -> None:
        tags = self._selected_line_geometry_tags()
        if len(tags) < 2:
            QMessageBox.information(
                self,
                "Join Geometry Lines",
                "Select at least two contiguous collinear Geometry Lines.",
            )
            return
        self._merge_selected_geometry_lines(tags)

    def _trim_extend_geometry_line(
        self,
        subject_tag: int,
        line_tags,
    ) -> None:
        tags = sorted({
            int(tag)
            for tag in line_tags
            if int(tag) in self.project.lines
        })
        subject_tag = int(subject_tag)
        if subject_tag not in tags:
            tags.append(subject_tag)
            tags.sort()
        if len(tags) != 2:
            QMessageBox.information(
                self,
                "Trim / Extend Geometry Line",
                "Select exactly two Geometry Lines, then right-click the "
                "Line to trim or extend.",
            )
            return
        target_tag = next(tag for tag in tags if tag != subject_tag)
        choices = ["Nearest endpoint", "Point I", "Point J"]
        choice, ok = QInputDialog.getItem(
            self,
            "Trim / Extend Geometry Line",
            (
                f"Line {subject_tag} will be trimmed/extended to "
                f"Line {target_tag}. Choose the endpoint to modify:"
            ),
            choices,
            0,
            False,
        )
        if not ok:
            return
        endpoint = {
            "Nearest endpoint": "nearest",
            "Point I": "i",
            "Point J": "j",
        }[choice]
        before = self.project.to_dict()
        try:
            result = trim_extend_line_to_line(
                self.project,
                subject_tag,
                target_tag,
                endpoint=endpoint,
                remesh=True,
            )
        except (TypeError, ValueError) as exc:
            self.project = ProjectDatabase.from_dict(before)
            self.model = self.project.model
            self._refresh_all()
            QMessageBox.warning(
                self,
                "Trim / Extend Geometry Line",
                str(exc),
            )
            return
        self.model = self.project.model
        self.viewport.clear_line_intersection_preview(render=False)
        self._refresh_all(
            f"{result.operation.capitalize()} Line {subject_tag} at "
            f"Point {result.intersection_point_tag} · "
            f"{len(result.created_line_tags)} target segment(s) created"
        )
        self.selection.clear()
        self.viewport.set_display_domain("geometry")
        self._show_line_geometry_properties(subject_tag)
        self._record_project_change(
            f"{result.operation.capitalize()} Geometry Line {subject_tag}",
            before,
        )

    def _merge_selected_geometry_lines(self, line_tags) -> None:
        tags = sorted({
            int(tag)
            for tag in line_tags
            if int(tag) in self.project.lines
        })
        if len(tags) < 2:
            QMessageBox.information(
                self,
                "Merge Collinear Lines",
                "Select at least two contiguous collinear Geometry Lines.",
            )
            return
        answer = QMessageBox.question(
            self,
            "Merge Collinear Lines",
            (
                f"Merge {len(tags)} selected Geometry Lines into one Line?\n\n"
                "The Lines must form one collinear chain and use compatible "
                "uniform mesh / FE recipes. This operation is undoable."
            ),
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        if answer != QMessageBox.Yes:
            return
        before = self.project.to_dict()
        try:
            result = merge_collinear_lines(
                self.project,
                tags,
                remesh=True,
            )
        except (TypeError, ValueError) as exc:
            self.project = ProjectDatabase.from_dict(before)
            self.model = self.project.model
            self._refresh_all()
            QMessageBox.warning(
                self,
                "Merge Collinear Lines",
                str(exc),
            )
            return
        self.model = self.project.model
        self.viewport.clear_line_intersection_preview(render=False)
        self._refresh_all(
            f"Merged {len(result.source_line_tags)} Line(s) into "
            f"Line {result.keeper_line_tag} · "
            f"{len(result.removed_line_tags)} Line object(s) removed"
        )
        self.selection.clear()
        self.viewport.set_display_domain("geometry")
        self._show_line_geometry_properties(result.keeper_line_tag)
        self._record_project_change(
            "Merge collinear Geometry Lines "
            + ", ".join(map(str, tags)),
            before,
        )

    def _divide_geometry_line(self, tag: int) -> None:
        tag = int(tag)
        line = self.project.lines.get(tag)
        if line is None:
            return
        modes = [
            "Equal geometry segments (N)",
            "Split at distance from Point I",
        ]
        mode, ok = QInputDialog.getItem(
            self,
            "Divide Geometry Line",
            f"Divide Line {tag} ({line.name}):",
            modes,
            0,
            False,
        )
        if not ok:
            return

        kwargs: dict[str, object] = {}
        if mode == modes[0]:
            count, ok = QInputDialog.getInt(
                self,
                "Divide Geometry Line",
                "Number of Geometry Line segments:",
                2,
                2,
                1000,
                1,
            )
            if not ok:
                return
            kwargs["segments"] = count
        else:
            point_i = self.project.points.get(line.point_i)
            point_j = self.project.points.get(line.point_j)
            if point_i is None or point_j is None:
                return
            length = math.sqrt(
                sum(
                    (
                        float(point_j.xyz[index])
                        - float(point_i.xyz[index])
                    ) ** 2
                    for index in range(3)
                )
            )
            distance, ok = QInputDialog.getDouble(
                self,
                "Divide Geometry Line",
                "Distance from Point I:",
                0.5 * length,
                1.0e-12,
                max(length - 1.0e-12, 1.0e-12),
                8,
            )
            if not ok:
                return
            kwargs["distance_from_i"] = distance

        before = self.project.to_dict()
        try:
            result = divide_line_geometry(
                self.project,
                tag,
                remesh=True,
                **kwargs,
            )
        except (TypeError, ValueError) as exc:
            self.project = ProjectDatabase.from_dict(before)
            self.model = self.project.model
            self._refresh_all()
            QMessageBox.warning(
                self,
                "Divide Geometry Line",
                str(exc),
            )
            return
        self.model = self.project.model
        self.viewport.clear_line_intersection_preview(render=False)
        self._refresh_all(
            f"Divided Line {tag} into {len(result.line_tags)} "
            f"Geometry Line segment(s) · "
            f"{len(result.created_point_tags)} new Point(s)"
        )
        self.selection.clear()
        self.viewport.set_display_domain("geometry")
        self._record_project_change(
            f"Divide Geometry Line {tag}",
            before,
        )

    def _copy_offset_geometry_lines(self, line_tags) -> None:
        tags = sorted({
            int(tag)
            for tag in line_tags
            if int(tag) in self.project.lines
        })
        if not tags:
            return
        dialog = VectorDialog(
            (
                "Copy / Offset Geometry Line"
                if len(tags) == 1
                else f"Copy / Offset {len(tags)} Geometry Lines"
            ),
            self,
            copies=True,
        )
        if not dialog.exec():
            return
        dx, dy, dz, copies = dialog.values()
        if abs(dx) + abs(dy) + abs(dz) <= 1.0e-15:
            QMessageBox.information(
                self,
                "Copy / Offset Geometry Line",
                "Enter a non-zero offset vector.",
            )
            return
        before = self.project.to_dict()
        try:
            result = copy_offset_line_geometry(
                self.project,
                tags,
                dx=dx,
                dy=dy,
                dz=dz,
                copies=copies,
                mesh=True,
            )
        except (TypeError, ValueError) as exc:
            self.project = ProjectDatabase.from_dict(before)
            self.model = self.project.model
            self._refresh_all()
            QMessageBox.warning(
                self,
                "Copy / Offset Geometry Line",
                str(exc),
            )
            return
        self.model = self.project.model
        self.viewport.clear_line_intersection_preview(render=False)
        self._refresh_all(
            f"Copied {len(tags)} Geometry Line(s) × {copies} · "
            f"{len(result.created_line_tags)} new Line(s) · "
            f"{len(result.created_point_tags)} new Point(s)"
        )
        self.selection.clear()
        self.viewport.set_display_domain("geometry")
        self._record_project_change(
            "Copy / offset Geometry Lines "
            + ", ".join(map(str, tags)),
            before,
        )

    def _clear_line_intersection_preview(self) -> None:
        self.viewport.clear_line_intersection_preview()
        self.status_message.setText("Line intersection preview cleared")

    def _inspect_line_geometry_intersections(self, line_tags) -> None:
        tags = sorted({
            int(tag)
            for tag in line_tags
            if int(tag) in self.project.lines
        })
        if len(tags) < 2:
            QMessageBox.information(
                self,
                "Geometry Line Intersections",
                "Select at least two Geometry Lines.",
            )
            return
        try:
            intersections = line_geometry_intersections(
                self.project,
                tags,
            )
        except (TypeError, ValueError) as exc:
            self.viewport.clear_line_intersection_preview()
            QMessageBox.warning(
                self,
                "Geometry Line Intersections",
                str(exc),
            )
            return
        if not intersections:
            self.viewport.clear_line_intersection_preview()
            QMessageBox.information(
                self,
                "Geometry Line Intersections",
                f"No Line intersections found across {len(tags)} Line(s).",
            )
            return
        self.viewport.show_line_intersection_preview(intersections)
        details = [
            (
                f"{index}. Lines {item.line_tags[0]} / {item.line_tags[1]} · "
                f"{item.kind} · "
                f"({item.point[0]:g}, {item.point[1]:g}, {item.point[2]:g})"
            )
            for index, item in enumerate(intersections[:30], start=1)
        ]
        if len(intersections) > 30:
            details.append(
                f"... and {len(intersections) - 30} more intersection(s)."
            )
        QMessageBox.information(
            self,
            "Geometry Line Intersections",
            "\n".join(details),
        )

