    def _tree_context_action_group(
        self,
        kind: str,
        action: QAction,
    ) -> int:
        """Return a stable UX group for a top-level Model Tree action."""
        label = " ".join(
            str(action.text()).replace("&", "").split()
        ).strip().lower()
        is_container = (
            str(kind).endswith("_root")
            or str(kind).endswith("_group")
        )

        # Destructive/clearing operations always live at the bottom.
        non_destructive_clear = (
            "clear result display",
            "clear current node selection",
            "clear quality map",
            "clear edge preview",
            "clear pressure preview",
            "clear intersection",
        )
        if label.startswith(("delete", "remove")):
            return 90
        if label.startswith("clear") and not label.startswith(
            non_destructive_clear
        ):
            return 90

        # View/selection commands are secondary and visually grouped.
        if (
            label.startswith(
                (
                    "view",
                    "zoom",
                    "hide",
                    "isolate",
                    "show all",
                    "show node",
                    "show element",
                    "clear result display",
                    "clear current node selection",
                    "clear quality map",
                    "clear edge preview",
                    "clear pressure preview",
                    "clear intersection",
                )
            )
            or label in {"selection", "visualize mesh quality"}
        ):
            return 70
        if label == "select" and str(kind) == "set":
            return 20
        if label.startswith("select"):
            return 25 if is_container else 70
        if label == "show":
            return 20

        # Object-management commands follow modeling/workflow commands.
        if label.startswith(
            (
                "duplicate",
                "copy",
                "rename",
                "update",
                "export",
            )
        ):
            return 60
        if label == "create named selection":
            return 10 if str(kind) == "named_sets_root" else 60

        # Diagnostics/previews come after direct modeling operations.
        if label.startswith(
            (
                "audit",
                "preview",
                "mesh quality",
                "inspect",
            )
        ):
            return 50

        # New/insert/draw/import commands are first on collection nodes.
        creation_prefixes = (
            "new ",
            "draw ",
            "insert ",
            "import ",
            "add ",
            "generate",
        )
        creation_submenus = {
            "analysis wizard",
            "add result request",
            "sketch plane",
            "generate",
        }
        if (
            label.startswith(creation_prefixes)
            or label in creation_submenus
        ):
            return 10 if is_container else 40

        # Direct object actions stay at the top for entity nodes.
        if label.startswith(
            (
                "properties",
                "edit",
                "configure",
                "activate",
                "set active",
                "set as active",
                "run",
                "evaluate",
                "apply",
                "open",
                "reveal",
                "show solver output",
                "show job manager",
                "check model",
            )
        ):
            return 20

        # Modeling/assignment submenus form the central workflow block.
        workflow_submenus = {
            "create",
            "definition",
            "assign",
            "modify",
            "modify geometry",
            "geometry",
            "mesh / fe",
            "mesh / fe tools",
            "line mesh",
            "surface mesh",
            "supports",
            "loads",
            "outputs / scopes",
            "network / audit",
            "plot",
            "dependencies",
            "used by",
        }
        if label in workflow_submenus or label.startswith(
            ("remesh", "apply support", "assign ")
        ):
            return 40

        return 50

    def _tree_context_submenu_group(
        self,
        title: str,
        action: QAction,
    ) -> int:
        """Return a stable UX group for supported Model Tree submenus."""
        label = " ".join(
            str(action.text()).replace("&", "").split()
        ).strip().lower()
        title_key = " ".join(str(title).split()).strip().lower()

        if label.startswith(("delete", "remove", "clear")):
            return 90

        if title_key == "view":
            if label.startswith("zoom"):
                return 10
            if label.startswith(("hide", "isolate")):
                return 20
            if label.startswith("show all"):
                return 30

        if title_key == "selection":
            if label.startswith("copy tag"):
                return 20
            if label.startswith("create named selection"):
                return 40

        if label.startswith("select"):
            return 70
        if label.startswith(
            (
                "preview",
                "inspect",
                "audit",
                "mesh quality",
                "visualize",
            )
        ):
            return 60
        if label.startswith(("copy", "duplicate", "rename", "update")):
            return 50
        if label.startswith(
            (
                "new ",
                "add ",
                "assign ",
                "apply ",
                "mass",
                "support",
                "constraint",
                "zerolength",
                "beam load",
                "surface pressure",
            )
        ):
            return 20
        return 30

    def _organize_tree_context_submenus(
        self,
        menu: QMenu,
    ) -> None:
        """Normalize only the hand-authored workflow submenus."""
        supported_titles = {
            "assign",
            "create",
            "modify",
            "modify geometry",
            "geometry",
            "mesh / fe",
            "mesh / fe tools",
            "supports",
            "loads",
            "outputs / scopes",
            "network / audit",
            "view",
            "selection",
            "line mesh",
            "surface mesh",
            "visualize mesh quality",
            "generate",
            "sketch plane",
        }

        for action in list(menu.actions()):
            submenu = action.menu()
            if submenu is None:
                continue
            title = " ".join(submenu.title().split()).strip()
            if title.lower() not in supported_titles:
                continue

            original_actions = list(submenu.actions())
            actions = [
                child
                for child in original_actions
                if not child.isSeparator()
            ]
            if not actions:
                continue

            ranked = sorted(
                enumerate(actions),
                key=lambda pair: (
                    self._tree_context_submenu_group(
                        title,
                        pair[1],
                    ),
                    pair[0],
                ),
            )
            for child in original_actions:
                submenu.removeAction(child)

            last_group: int | None = None
            for _, child in ranked:
                group = self._tree_context_submenu_group(
                    title,
                    child,
                )
                if last_group is not None and group != last_group:
                    submenu.addSeparator()
                submenu.addAction(child)
                last_group = group

    def _organize_tree_context_menu(
        self,
        menu: QMenu,
        kind: str,
    ) -> None:
        """Apply one predictable order to every Model Tree context menu."""
        self._organize_tree_context_submenus(menu)
        original_actions = list(menu.actions())
        actions = [
            action
            for action in original_actions
            if not action.isSeparator()
        ]
        if not actions:
            return

        ranked = sorted(
            enumerate(actions),
            key=lambda pair: (
                self._tree_context_action_group(kind, pair[1]),
                pair[0],
            ),
        )

        for action in original_actions:
            menu.removeAction(action)

        last_group: int | None = None
        for _, action in ranked:
            group = self._tree_context_action_group(kind, action)
            if last_group is not None and group != last_group:
                menu.addSeparator()
            menu.addAction(action)
            last_group = group

    def _append_tree_ai_action(
        self,
        menu: QMenu,
        kind: str,
        value: object,
    ) -> None:
        actions = menu.actions()
        if actions and not actions[-1].isSeparator():
            menu.addSeparator()
        ask_ai = menu.addAction("Ask AI about this")
        ask_ai.setIcon(studio_icon("ask-ai-tree"))
        ask_ai.triggered.connect(
            lambda checked=False, k=str(kind), v=value:
            self._ask_ai_about_tree_item(k, v)
        )

    def _show_tree_context_menu(self, position) -> None:
        item = self.tree.itemAt(position)
        if item is None:
            return

        # Match standard tree UX: right-clicking an unselected item first
        # makes that item the active selection. Preserve an existing
        # multi-selection when the clicked item already belongs to it.
        if not item.isSelected():
            self.tree.clearSelection()
            self.tree.setCurrentItem(item)
            item.setSelected(True)

        payload = item.data(0, Qt.UserRole)
        if not payload:
            return

        kind, value = payload
        menu = QMenu(self)

        def exec_menu() -> None:
            # Keep every Model Tree menu consistent before appending AI help.
            # Collection nodes start with creation/import actions; entity
            # nodes start with direct object actions; destructive commands
            # stay at the bottom. AI remains the final, separate action.
            self._organize_tree_context_menu(menu, str(kind))
            self._append_tree_ai_action(menu, str(kind), value)
            menu.exec(self.tree.viewport().mapToGlobal(position))

        if kind == "model_root":
            properties = menu.addAction("Properties")
            properties.triggered.connect(
                lambda: self._show_tree_root_properties("model_root")
            )
            menu.addAction(self.actions["check_model"])
            menu.addAction(self.actions["run"])
            menu.addSeparator()
            menu.addAction(self.actions["origin_axes"])
            show_all = menu.addAction("Show All")
            show_all.triggered.connect(self._show_all)
            exec_menu()
            return

        if kind == "geometry_root":
            properties = menu.addAction("Properties")
            properties.triggered.connect(
                lambda: self._show_tree_root_properties("geometry_root")
            )
            point_action = menu.addAction("New Point...")
            point_action.triggered.connect(self._create_point_geometry)
            line_pick = menu.addAction("Draw Polyline")
            line_pick.triggered.connect(
                self._activate_geometry_line_pick_tool
            )
            line_action = menu.addAction("New Line by Input...")
            line_action.triggered.connect(self._create_line_geometry)
            surface_pick = menu.addAction("Draw Rectangle")
            surface_pick.triggered.connect(
                self._activate_geometry_surface_pick_tool
            )
            surface_action = menu.addAction("New Surface by Input...")
            surface_action.triggered.connect(self._create_surface_geometry)

            menu.addSeparator()
            plane_menu = menu.addMenu("Sketch Plane")
            plane_menu.addAction(self.actions["sketch_plane_offset"])
            plane_menu.addAction(self.actions["sketch_plane_3point"])

            generator_menu = menu.addMenu("Generate")
            quick_column = generator_menu.addAction("1D Test Specimen...")
            quick_column.triggered.connect(self._show_test_column_wizard)
            quick_2d = generator_menu.addAction("2D Frame...")
            quick_2d.triggered.connect(self._show_frame_grid_2d)
            grid_action = generator_menu.addAction("3D Frame Grid...")
            grid_action.triggered.connect(self._show_frame_grid)

            menu.addSeparator()
            menu.addAction(self.actions["origin_axes"])
            exec_menu()
            return

        if kind == "fe_model_root":
            properties = menu.addAction("Properties")
            properties.triggered.connect(
                lambda: self._show_tree_root_properties("fe_model_root")
            )
            node_action = menu.addAction("New Node...")
            node_action.triggered.connect(self._create_node)
            frame_action = menu.addAction("New Frame...")
            frame_action.triggered.connect(self._create_element)
            truss_action = menu.addAction("New Truss...")
            truss_action.triggered.connect(self._create_truss)
            shell_action = menu.addAction("New Shell Element...")
            shell_action.triggered.connect(self._create_shell)
            connection_action = menu.addAction(
                "New Connection / Joint..."
            )
            connection_action.triggered.connect(self._create_connection)
            exec_menu()
            return

        if kind == "mass_root":
            properties = menu.addAction("Properties")
